use serde_json::{json,Value};
use base64::{engine::general_purpose::STANDARD,Engine};
use sha2::{Digest,Sha256};
use sqlx::{Row,Sqlite,Transaction};
use std::{collections::{BTreeMap,HashSet},fs,io::{Read,Seek,SeekFrom,Write},path::{Path,PathBuf}};
use zip::{write::SimpleFileOptions,CompressionMethod,ZipWriter};
use crate::persistence::Store;
const EXPORT_VERSION:i64=1;
fn err(m:&str)->sqlx::Error{sqlx::Error::Protocol(m.into())}
fn root(store:&Store)->Result<PathBuf,sqlx::Error>{store.database_path().and_then(Path::parent).map(Path::to_path_buf).ok_or_else(||err("export unavailable for in-memory storage"))}
fn dir(root:&Path,profile:&str)->PathBuf{root.join("exports").join(profile)}
fn safe(s:&str)->bool{!s.is_empty()&&s.len()<=80&&s.bytes().all(|b|b.is_ascii_alphanumeric()||b==b'-'||b==b'_')}
fn id(request:&str)->String{let h=format!("{:x}",Sha256::digest(format!("ai-home:profile-export:{request}").as_bytes()));format!("export-{}",&h[..32])}
fn hash_file(path:&Path)->Result<String,sqlx::Error>{let mut f=fs::File::open(path).map_err(|_|err("export read failed"))?;let mut h=Sha256::new();let mut b=[0u8;65536];loop{let n=f.read(&mut b).map_err(|_|err("export read failed"))?;if n==0{break}h.update(&b[..n]);}Ok(format!("{:x}",h.finalize()))}
async fn bodies(tx:&mut Transaction<'_,Sqlite>,table:&str,profile:&str,order:&str)->Result<Vec<Value>,sqlx::Error>{let sql=format!("SELECT body FROM {table} WHERE profile_id=? ORDER BY {order}");let rows=sqlx::query(&sql).bind(profile).fetch_all(&mut **tx).await?;rows.into_iter().map(|r|serde_json::from_str(r.get::<&str,_>("body")).map_err(|_|err("invalid export record"))).collect()}
fn add(zip:&mut ZipWriter<fs::File>,entries:&mut Vec<Value>,name:&str,bytes:&[u8])->Result<(),sqlx::Error>{let opts=SimpleFileOptions::default().compression_method(CompressionMethod::Deflated);zip.start_file(name,opts).map_err(|_|err("export zip write failed"))?;zip.write_all(bytes).map_err(|_|err("export zip write failed"))?;entries.push(json!({"name":name,"sizeBytes":bytes.len(),"sha256":format!("{:x}",Sha256::digest(bytes))}));Ok(())}
fn json_bytes(v:&Value)->Vec<u8>{serde_json::to_vec_pretty(v).unwrap_or_else(|_|b"null".to_vec())}
fn clean_name(s:&str)->String{let out:String=s.chars().map(|c|if c.is_ascii_alphanumeric()||matches!(c,'-'|'_'|' '){c}else{'_'}).collect();let t=out.trim();if t.is_empty(){"conversation".into()}else{t.chars().take(80).collect()}}
fn portable_connection(c:&Value)->Value{json!({"schemaVersion":1,"id":c["id"],"profileId":c["profileId"],"revision":c["revision"],"createdAt":c["createdAt"],"providerKind":c["providerKind"],"normalizedEndpoint":c["normalizedEndpoint"],"credentialRevision":c["credentialRevision"],"label":c["label"],"status":c["status"],"requiresCredentialRebind":true})}
pub async fn create(store:&Store,profile:&str,request:&str)->Result<Value,sqlx::Error>{
 let root=root(store)?;let outdir=dir(&root,profile);fs::create_dir_all(&outdir).map_err(|_|err("export directory create failed"))?;let eid=id(request);let path=outdir.join(format!("{eid}.zip"));let meta=outdir.join(format!("{eid}.json"));if meta.is_file()&&path.is_file(){let v:Value=serde_json::from_slice(&fs::read(&meta).map_err(|_|err("export metadata read failed"))?).map_err(|_|err("export metadata invalid"))?;if v["requestId"]==request&&v["profileId"]==profile&&hash_file(&path)?==v["sha256"]{let mut r=v.clone();r.as_object_mut().unwrap().remove("requestId");return Ok(r)}return Err(err("export idempotency conflict"))}
 let mut tx=store.pool.begin().await?;let prow=sqlx::query("SELECT body FROM profiles WHERE id=?").bind(profile).fetch_optional(&mut *tx).await?.ok_or_else(||err("profile not found"))?;let profile_body:Value=serde_json::from_str(prow.get::<&str,_>("body")).map_err(|_|err("invalid profile"))?;
 let connections:Vec<Value>=bodies(&mut tx,"connections",profile,"id").await?.iter().map(portable_connection).collect();let routes=bodies(&mut tx,"routes",profile,"id").await?;
 let conversations=bodies(&mut tx,"conversations",profile,"id").await?;let messages=bodies(&mut tx,"messages",profile,"conversation_id, sequence").await?;let segments=bodies(&mut tx,"context_segments",profile,"conversation_id, first_message_sequence").await?;
 let records=bodies(&mut tx,"memory_records",profile,"id").await?;let versions=bodies(&mut tx,"memory_versions",profile,"record_id, id").await?;let proposals=bodies(&mut tx,"memory_proposals",profile,"id").await?;let decisions=bodies(&mut tx,"memory_decisions",profile,"id").await?;let memmeta=bodies(&mut tx,"memory_metadata",profile,"record_id").await?;let vermeta=bodies(&mut tx,"memory_version_metadata",profile,"version_id").await?;
 let profile_materials=bodies(&mut tx,"profile_import_materials",profile,"id").await?;let conv_materials=bodies(&mut tx,"import_materials",profile,"conversation_id, id").await?;let attachments=bodies(&mut tx,"attachments",profile,"conversation_id, id").await?;let knowledge=bodies(&mut tx,"knowledge_sources",profile,"id").await?;let guidance=bodies(&mut tx,"persistent_guidance",profile,"id").await?;
 let file=fs::File::create(&path).map_err(|_|err("export create failed"))?;let mut zip=ZipWriter::new(file);let mut entries=vec![];
 let excluded=vec!["credentials/vault secrets","provider private replay","receipts and request fingerprints","raw provider payloads","private reflection/dream records, self notes, values and review receipts"];
 let readme=format!("AI Home portable profile export\nProfile: {}\nCreated by AI Home\n\nIncludes readable conversations, structured JSON, memory provenance, portable route/connection configuration and imported source originals. Provider credentials are intentionally absent; reconnect credentials after import/use elsewhere.\nExcluded: {}.\n",profile,excluded.join(", "));add(&mut zip,&mut entries,"README.txt",readme.as_bytes())?;
 add(&mut zip,&mut entries,"data/profile.json",&json_bytes(&profile_body))?;add(&mut zip,&mut entries,"data/connections.portable.json",&json_bytes(&json!({"requiresCredentialRebind":true,"items":connections})))?;add(&mut zip,&mut entries,"data/routes.json",&json_bytes(&json!(&routes)))?;add(&mut zip,&mut entries,"data/conversations.json",&json_bytes(&json!(&conversations)))?;add(&mut zip,&mut entries,"data/messages.json",&json_bytes(&json!(&messages)))?;add(&mut zip,&mut entries,"data/context-segments.json",&json_bytes(&json!(&segments)))?;
 add(&mut zip,&mut entries,"data/memory-records.json",&json_bytes(&json!(&records)))?;add(&mut zip,&mut entries,"data/memory-versions.json",&json_bytes(&json!(&versions)))?;add(&mut zip,&mut entries,"data/memory-proposals.json",&json_bytes(&json!(&proposals)))?;add(&mut zip,&mut entries,"data/memory-decisions.json",&json_bytes(&json!(&decisions)))?;add(&mut zip,&mut entries,"data/memory-metadata.json",&json_bytes(&json!(&memmeta)))?;add(&mut zip,&mut entries,"data/memory-version-metadata.json",&json_bytes(&json!(&vermeta)))?;
 add(&mut zip,&mut entries,"data/profile-import-materials.json",&json_bytes(&json!(&profile_materials)))?;add(&mut zip,&mut entries,"data/conversation-import-materials.json",&json_bytes(&json!(&conv_materials)))?;add(&mut zip,&mut entries,"data/attachments.json",&json_bytes(&json!(&attachments)))?;add(&mut zip,&mut entries,"data/knowledge-sources.json",&json_bytes(&json!(&knowledge)))?;add(&mut zip,&mut entries,"data/persistent-guidance.json",&json_bytes(&json!(&guidance)))?;
 let mut all_txt=String::from("AI Home conversations\n\n");let mut by_conv:BTreeMap<String,Vec<&Value>>=BTreeMap::new();for m in &messages{if let Some(c)=m["conversationId"].as_str(){by_conv.entry(c.into()).or_default().push(m)}}for (idx,c) in conversations.iter().enumerate(){let cid=c["id"].as_str().unwrap_or("");let title=c["title"].as_str().unwrap_or("Conversation");let mut md=format!("# {}\n\nConversation ID: `{}`\nLanguage: {}\nStatus: {}\n\n",title,cid,c["language"].as_str().unwrap_or("unknown"),c["status"].as_str().unwrap_or("unknown"));if let Some(ms)=by_conv.get(cid){for m in ms{md.push_str(&format!("## {} · {}\n\n{}\n\n",m["role"].as_str().unwrap_or("unknown"),m["createdAt"].as_str().unwrap_or(""),m["content"].as_str().unwrap_or("")));}}let name=format!("conversations/{:04}-{}.md",idx+1,clean_name(title));add(&mut zip,&mut entries,&name,md.as_bytes())?;all_txt.push_str(&format!("===== {} =====\n{}\n",title,md.replace("# ","").replace("## ","")));}add(&mut zip,&mut entries,"conversations.txt",all_txt.as_bytes())?;
 let mut original_ids=HashSet::new();for m in profile_materials.iter().chain(conv_materials.iter()){if let Some(b)=m["originalBlobId"].as_str(){original_ids.insert(b.to_string());}}
 for bid in original_ids{let row=sqlx::query("SELECT sha256,bytes FROM import_blobs WHERE profile_id=? AND id=?").bind(profile).bind(&bid).fetch_optional(&mut *tx).await?;if let Some(r)=row{let bytes:Vec<u8>=r.get("bytes");let sha:String=r.get("sha256");add(&mut zip,&mut entries,&format!("sources/{bid}-{sha}.bin"),&bytes)?;}}tx.commit().await?;
 let created=chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Millis,true);let manifest=json!({"exportVersion":EXPORT_VERSION,"id":eid,"profileId":profile,"createdAt":created,"schemaVersion":15,"entries":entries.clone(),"excluded":excluded.clone()});add(&mut zip,&mut entries,"manifest.json",&json_bytes(&manifest))?;zip.finish().map_err(|_|err("export zip finalize failed"))?;
 let size=fs::metadata(&path).map_err(|_|err("export metadata failed"))?.len();let sha=hash_file(&path)?;let result=json!({"exportVersion":EXPORT_VERSION,"id":eid,"profileId":profile,"createdAt":created,"fileName":format!("{eid}.zip"),"sizeBytes":size,"sha256":sha,"entryCount":entries.len(),"excluded":excluded.clone()});let saved=json!({"requestId":request,"exportVersion":EXPORT_VERSION,"id":eid,"profileId":profile,"createdAt":created,"fileName":format!("{eid}.zip"),"sizeBytes":size,"sha256":sha,"entryCount":entries.len(),"excluded":excluded});fs::write(&meta,serde_json::to_vec_pretty(&saved).map_err(|_|err("export metadata invalid"))?).map_err(|_|err("export metadata write failed"))?;Ok(result)
}
pub fn list(store:&Store,profile:&str)->Result<Value,sqlx::Error>{let root=root(store)?;let d=dir(&root,profile);if !d.exists(){return Ok(json!({"items":[]}))}let mut items=vec![];for e in fs::read_dir(d).map_err(|_|err("export directory read failed"))?{let p=e.map_err(|_|err("export directory entry failed"))?.path();if p.extension().and_then(|x|x.to_str())!=Some("json"){continue}let mut v:Value=serde_json::from_slice(&fs::read(&p).map_err(|_|err("export metadata read failed"))?).map_err(|_|err("export metadata invalid"))?;if v["profileId"]==profile&&v["id"].as_str().is_some_and(safe){v.as_object_mut().unwrap().remove("requestId");items.push(v)}}items.sort_by(|a,b|b["createdAt"].as_str().cmp(&a["createdAt"].as_str()));Ok(json!({"items":items}))}

pub fn read(store:&Store,profile:&str,id:&str,offset:usize)->Result<Value,sqlx::Error>{
 if !safe(id){return Err(err("invalid export id"))}let root=root(store)?;let d=dir(&root,profile);let meta=d.join(format!("{id}.json"));let path=d.join(format!("{id}.zip"));if !meta.is_file()||!path.is_file(){return Err(err("export missing"))}let m:Value=serde_json::from_slice(&fs::read(meta).map_err(|_|err("export metadata read failed"))?).map_err(|_|err("export metadata invalid"))?;if m["profileId"]!=profile||m["id"]!=id{return Err(err("export scope mismatch"))}let total=fs::metadata(&path).map_err(|_|err("export read failed"))?.len() as usize;if offset>total{return Err(err("invalid export offset"))}let end=(offset+1024*1024).min(total);let mut f=fs::File::open(&path).map_err(|_|err("export read failed"))?;f.seek(SeekFrom::Start(offset as u64)).map_err(|_|err("export read failed"))?;let mut bytes=vec![0u8;end-offset];f.read_exact(&mut bytes).map_err(|_|err("export read failed"))?;Ok(json!({"dataBase64":STANDARD.encode(&bytes),"nextOffset":if end<total{end}else{0},"totalBytes":total,"fileName":m["fileName"],"sha256":m["sha256"]}))
}
